    } else {
        float bound = hit_start_z - broadphase_radius;
        if (bound > hurt_start_copy.z && bound > hurt_end->z) {
            return false;
        }
        bound = hit_end->z;
        bound += broadphase_radius;
        if (bound < hurt_start_copy.z && bound < hurt_end->z) {
            return false;
        }
    }
    // Solve closest points between the two segment axes.
    hit_delta.x = hit_end_x - hit_start_copy.x;
    hit_delta.y = hit_end->y - hit_start_copy.y;
    hit_delta.z = hit_end->z - hit_start_copy.z;
    hurt_end_x = hurt_end->x;
    axis.x = hurt_end_x - (offset.x = hurt_start_copy.x);
    hurt_end_y = hurt_end->y;
    hurt_start_y = hurt_start_copy.y;
    axis.y = hurt_end_y - hurt_start_y;
    hurt_end_z = hurt_end->z;
    hurt_start_z = hurt_start_copy.z;
    axis.z = hurt_end_z - hurt_start_z;
    midpoint.y = hit_delta.y;
    separation.y = midpoint.y * midpoint.y;
    separation.x = hit_delta.x * hit_delta.x;
    {
        PAD_STACK(4);
        separation.z = hit_delta.z * hit_delta.z;
    }
    hit_len_sq = separation.z + (separation.x + separation.y);
    offset.x = hit_start_copy.x - offset.x;
    offset.y = hit_start_copy.y - hurt_start_y;
    (void) hurt_end_z;
    offset.z = hit_start_copy.z - hurt_start_z;
    hurt_start_dot = PF_SlippiMulAddF32(axis.z, offset.z, PF_SlippiMulAddF32(axis.x, offset.x, axis.y * offset.y));
    (void) hurt_end_y;
    (void) hurt_end_x;
    segment_dot = PF_SlippiMulAddF32(hit_delta.z, axis.z, PF_SlippiMulAddF32(hit_delta.x, axis.x, midpoint.y * axis.y));
    {
        PAD_STACK(4);
        hit_start_dot = PF_SlippiMulAddF32(hit_delta.z, offset.z, PF_SlippiMulAddF32(hit_delta.x, offset.x, midpoint.y * offset.y));
    }
    hurt_len_sq = axis.y * axis.y;
    hurt_len_sq = PF_SlippiMulAddF32(axis.x, axis.x, hurt_len_sq);
    hurt_len_sq = PF_SlippiMulAddF32(axis.z, axis.z, hurt_len_sq);
    closest_denom = PF_SlippiMulAddF32(hit_len_sq, hurt_len_sq, -(segment_dot * segment_dot));
    (void) hit_len_sq;
    if (approximatelyZero(hurt_len_sq)) {
        if (approximatelyZero(hit_len_sq)) {
            hit_param = 0.0F;
            hurt_param = hit_param;
        } else {
            hurt_param = 0.0F;
            hit_param = -hit_start_dot / hit_len_sq;
            if (hit_param > 1.0) {
                hit_param = 1.0F;
            } else if (hit_param < 0.0) {
                hit_param = hurt_param;
            }
        }
    } else {
        if (approximatelyZero(closest_denom)) {
            midpoint.x = (float) PF_SlippiMulAddF64(0.5, axis.x, hurt_start_copy.x);
            midpoint.y = (float) PF_SlippiMulAddF64(0.5, axis.y, hurt_start_y);
            midpoint.z = (float) PF_SlippiMulAddF64(0.5, axis.z, hurt_start_z);
            separation.x = hit_start_copy.x - midpoint.x;
            midpoint.x = hit_end->x - midpoint.x;
            separation.y = hit_start_copy.y - midpoint.y;
            midpoint.y = hit_end->y - midpoint.y;
            separation.z = hit_start_copy.z - midpoint.z;
            midpoint.z = hit_end->z - midpoint.z;
            if ((PF_SlippiMulAddF32(separation.z, separation.z, PF_SlippiMulAddF32(separation.x, separation.x, separation.y * separation.y))) <
                (PF_SlippiMulAddF32(midpoint.z, midpoint.z, PF_SlippiMulAddF32(midpoint.x, midpoint.x, midpoint.y * midpoint.y))))
            {
                Vec3 a2;
                Vec3 d1;
                Vec3 c3;
                PAD_STACK(4);
                c3 = *hurt_start;
                hit_param = 0.0F;
                d1.x = hurt_end_x - hurt_start->x;
                d1.y = hurt_end_y - hurt_start->y;
                d1.z = hurt_end_z - hurt_start->z;
                {
                    float dot;

                    a2 = *hit_start;
                    dot = PF_SlippiMulAddF32(d1.z, c3.z - a2.z, PF_SlippiMulAddF32(d1.x, c3.x - a2.x, d1.y * (c3.y - a2.y)));
                    hurt_param_from_hit_start =
                        -dot /
                        (PF_SlippiMulAddF32(d1.z, d1.z, PF_SlippiMulAddF32(d1.x, d1.x, d1.y * d1.y)));
                }
                if (hurt_param_from_hit_start > 1.0) {
                    hurt_param_from_hit_start = 1.0F;
                } else if (hurt_param_from_hit_start < 0.0) {
                    hurt_param_from_hit_start = hit_param;
                }
                hurt_param = hurt_param_from_hit_start;
            } else {
                float dot;
                Vec3 b0;
                Vec3 d1;
                Vec3 c2;
                c2 = *hurt_start;
                hit_param = 1.0F;
                d1.x = hurt_end_x - hurt_start->x;
                d1.y = hurt_end_y - hurt_start->y;
                d1.z = hurt_end_z - hurt_start->z;
                {
                    b0 = *hit_end;
                    dot = PF_SlippiMulAddF32(d1.z, c2.z - b0.z, PF_SlippiMulAddF32(d1.x, c2.x - b0.x, d1.y * (c2.y - b0.y)));
                    hurt_param_from_hit_end =
                        -dot /
                        (PF_SlippiMulAddF32(d1.z, d1.z, PF_SlippiMulAddF32(d1.x, d1.x, d1.y * d1.y)));
                }
                if (hurt_param_from_hit_end > 1.0) {
                    hurt_param_from_hit_end = hit_param;
                } else if (hurt_param_from_hit_end < 0.0) {
                    hurt_param_from_hit_end = 0.0F;
                }
                hurt_param = hurt_param_from_hit_end;
            }
        } else {
            hit_param = PF_SlippiMulAddF32(segment_dot, hurt_start_dot, -(hurt_len_sq * hit_start_dot)) /
                        closest_denom;
            hurt_param = PF_SlippiMulAddF32(hit_len_sq, hurt_start_dot, -(segment_dot * hit_start_dot)) /
                         closest_denom;
            if ((hit_param > 1.0) || (hit_param < 0.0) || (hurt_param > 1.0) ||
                (hurt_param < 0.0))
            {
                float hit_endpoint_dist_sq;
                float hit_endpoint_param;
                float hurt_endpoint_param;
                float hurt_endpoint_dist_sq;

                // If the unconstrained solution leaves either segment, compare
                // the nearest endpoint projection from each axis.
                if (hit_param < 0.0) {
                    hit_endpoint_param = 0.0F;
                    hit_endpoint_dist_sq =
                        lbColl_80005EBC(hurt_start, hurt_end, hit_start,
                                        &candidate_hurt_param);
                } else {
                    hit_endpoint_param = 1.0F;
                    hit_endpoint_dist_sq = lbColl_80005EBC(
                        hurt_start, hurt_end, hit_end, &candidate_hurt_param);
                }
                if (hurt_param < 0.0) {
                    hurt_endpoint_param = 0.0F;
                    hurt_endpoint_dist_sq = lbColl_80005EBC(
                        hit_start, hit_end, hurt_start, &candidate_hit_param);
                } else {
                    hurt_endpoint_param = 1.0F;
                    hurt_endpoint_dist_sq = lbColl_80005EBC(
                        hit_start, hit_end, hurt_end, &candidate_hit_param);
                }
                if (hit_endpoint_dist_sq < hurt_endpoint_dist_sq) {
                    hit_param = hit_endpoint_param;
                    hurt_param = candidate_hurt_param;
                } else {
                    hit_param = candidate_hit_param;
                    hurt_param = hurt_endpoint_param;
                }
            }
        }
    }
    hit_closest->x = PF_SlippiMulAddF32(hit_delta.x, hit_param, hit_start_copy.x);
    hit_closest->y = PF_SlippiMulAddF32(hit_delta.y, hit_param, hit_start_copy.y);
    hit_closest->z = PF_SlippiMulAddF32(hit_delta.z, hit_param, hit_start_copy.z);
    hurt_closest->x = PF_SlippiMulAddF32(axis.x, hurt_param, hurt_start_copy.x);
    hurt_closest->y = PF_SlippiMulAddF32(axis.y, hurt_param, hurt_start_y);
    hurt_closest->z = PF_SlippiMulAddF32(axis.z, hurt_param, hurt_start_z);
    separation.x = hit_closest->x - hurt_closest->x;
    separation.y = hit_closest->y - hurt_closest->y;
    separation.z = hit_closest->z - hurt_closest->z;
    closest_dist_sq =
        PF_SlippiMulAddF32(separation.z, separation.z,
            PF_SlippiMulAddF32(separation.x, separation.x, separation.y * separation.y));
    axis.x = sqrtf(closest_dist_sq);
    if (approximatelyZero(axis.x)) {
        *out_overlap = (hit_radius + hurt_radius) - axis.x;
        *out_contact_pos = *hit_closest;
        return true;
    }

    // Measure the hurt radius in the matrix's local space for scaled bones.
    HSD_MtxInverse(hurt_mtx, inv_hurt_mtx);
    PSMTXMultVec(inv_hurt_mtx, hit_closest, &hit_start_copy);
    PSMTXMultVec(inv_hurt_mtx, hurt_closest, &hit_delta);
    separation.x = hit_start_copy.x - hit_delta.x;
    separation.y = hit_start_copy.y - hit_delta.y;
    separation.z = hit_start_copy.z - hit_delta.z;
    local_dist_sq =
        PF_SlippiMulAddF32(separation.z, separation.z,
            PF_SlippiMulAddF32(separation.x, separation.x, separation.y * separation.y));
    local_dist_sq = sqrtf(local_dist_sq);
    scaled_hurt_radius = (hurt_radius * axis.x) / local_dist_sq;
    contact_lerp = scaled_hurt_radius / axis.x;
    allowed_distance = hit_radius + scaled_hurt_radius;
    *out_overlap = allowed_distance - axis.x;
    hurt_closest_x = hurt_closest->x;
    out_contact_pos->x =
        PF_SlippiMulAddF32(contact_lerp, hit_closest->x - hurt_closest_x, hurt_closest_x);
    hurt_closest_y = hurt_closest->y;
    out_contact_pos->y =
        PF_SlippiMulAddF32(contact_lerp, hit_closest->y - hurt_closest_y, hurt_closest_y);
    hurt_closest_z = hurt_closest->z;
    out_contact_pos->z =
        PF_SlippiMulAddF32(contact_lerp, hit_closest->z - hurt_closest_z, hurt_closest_z);
    if (allowed_distance < axis.x) {
        return false;
    }
    return true;
}
